  NavigationMenuIndicator,
  NavigationMenuItem,
  NavigationMenuLink,
  NavigationMenuList,
  NavigationMenuTrigger,
  NavigationMenuViewport,
  navigationMenuTriggerStyle,
};

"use client";

import * as React from "react";
import { cn } from "@/lib/utils";
import {
  NavigationMenu as BaseNavigationMenu,
  NavigationMenuContent as BaseNavigationMenuContent,
  NavigationMenuList as BaseNavigationMenuList,
  NavigationMenuViewport as BaseNavigationMenuViewport,
  NavigationMenuIndicator,
  NavigationMenuItem,
  NavigationMenuLink,
  NavigationMenuTrigger,
} from "../navigation-menu";

export interface NavigationMenuListProps extends React.ComponentProps<typeof BaseNavigationMenuList> {
  glow?: boolean;
}

export interface NavigationMenuContentProps extends React.ComponentProps<typeof BaseNavigationMenuContent> {
  glow?: boolean;
}

export interface NavigationMenuViewportProps extends React.ComponentProps<typeof BaseNavigationMenuViewport> {
  glow?: boolean;
}

/**
 * Sistine Navigation Menu - Enhanced navigation menu with glassy effects
 */
export const NavigationMenuList = React.forwardRef<React.ElementRef<typeof BaseNavigationMenuList>, NavigationMenuListProps>(
  ({ className, variant = "glass", glow = false, ...props }, ref) => {
    return <BaseNavigationMenuList ref={ref} variant={variant} className={cn(glow && "glass-glow", className)} {...props} />;
  },
);
NavigationMenuList.displayName = "NavigationMenuList";

export const NavigationMenuContent = React.forwardRef<React.ElementRef<typeof BaseNavigationMenuContent>, NavigationMenuContentProps>(
  ({ className, variant = "glass", glow = false, ...props }, ref) => {
    return <BaseNavigationMenuContent ref={ref} variant={variant} className={cn(glow && "glass-glow", className)} {...props} />;
  },
);
NavigationMenuContent.displayName = "NavigationMenuContent";

export const NavigationMenuViewport = React.forwardRef<React.ElementRef<typeof BaseNavigationMenuViewport>, NavigationMenuViewportProps>(
  ({ className, variant = "glass", glow = false, ...props }, ref) => {
    return <BaseNavigationMenuViewport ref={ref} variant={variant} className={cn(glow && "glass-glow", className)} {...props} />;
  },
);
NavigationMenuViewport.displayName = "NavigationMenuViewport";

export { BaseNavigationMenu as NavigationMenu, NavigationMenuIndicator, NavigationMenuItem, NavigationMenuLink, NavigationMenuTrigger };
